def max_sum(nums):
    n = len(nums)
    # Initialize two lists to store the maximum sum of increasing and decreasing subsequences
    inc, dec = [0] * n, [0] * n

    # Fill the increasing subsequence list with the maximum sum of increasing subsequences ending at each number
    for i in range(n):
        num = nums[i]
        inc[i] = num
        for j in range(i):
            if nums[j] < num and inc[j] + num > inc[i]:
                inc[i] = inc[j] + num

    # Fill the decreasing subsequence list with the maximum sum of decreasing subsequences starting at each number
    for i in reversed(range(n)):
        num = nums[i]
        dec[i] = num
        for j in range(i + 1, n):
            if nums[j] < num and dec[j] + num > dec[i]:
                dec[i] = dec[j] + num

    # Find the maximum sum of a bitonic subsequence
    max_sum = 0
    for i in range(n):
        if inc[i] + dec[i] > max_sum:
            max_sum = inc[i] + dec[i]

    return max_sum

