import math

def is_prime(num):
    """Check if a number is a prime."""
    if num <= 1:
        return False
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

def newman_prime(n):
    """Calculate the nth Newman–Shanks–Williams prime."""
    if n == 1:
        return 7  # P1 is 1, but the first NSW prime is P2 = 7
    elif n == 2:
        return 17  # The second NSW prime
    else:
        p_n_minus_2 = 7
        p_n_minus_1 = 17
        for _ in range(3, n + 1):
            p_n = 4 * p_n_minus_1 - p_n_minus_2
            if is_prime(p_n):
                p_n_minus_2 = p_n_minus_1
                p_n_minus_1 = p_n
        return p_n_minus_1

